/* 部位锚点（各自 viewBox 坐标系）。renderHumanPortrait 按 part 名查表，
   在该坐标画可见色点 + 把引线连到对应标签卡。换剪影只需重标这张表。 */
window.BODY_ANCHORS = {
  man: {
    head:[363,100], mouth:[368,190], heart:[378,420], shoulder:[496,322],
    leftHand:[300,690], rightHand:[470,705], legs:[372,880], feet:[372,1010],
  },
  woman: {
    head:[1150,330], leftEye:[1095,300], rightEye:[1205,300],
    leftEar:[985,350], rightEar:[1315,350], heart:[1150,880],
    leftHand:[450,760], rightHand:[1890,760], base:[1150,1470],
  },
};

/* 把剪影注入到一个 <svg>（设 viewBox + markup）。opts.color 可强制单色。 */
window.injectSilhouette = function (svg, kind, opts) {
  kind = kind || 'man'; opts = opts || {};
  var data = window.SILHOUETTE[kind] || window.SILHOUETTE.man;
  svg.setAttribute('viewBox', data.viewBox);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  svg.innerHTML = data.markup;
  if (opts.color) {
    svg.querySelectorAll('path').forEach(function (p) {
      p.style.fill = opts.color; p.setAttribute('fill', opts.color);
    });
  }
  if (opts.opacity != null) svg.style.opacity = opts.opacity;
  return svg;
};

/* k 个标签铺进 R 行，居中错落（1=中间，2=首尾，3=均匀）。 */
function _hpSpreadRows(k, R) {
  if (k <= 0) return [];
  if (k >= R) { var a = []; for (var i = 1; i <= R; i++) a.push(i); return a.slice(0, k); }
  if (k === 1) return [Math.ceil(R / 2)];
  var rows = [];
  for (var j = 0; j < k; j++) rows.push(1 + Math.round(j * (R - 1) / (k - 1)));
  return rows;
}

window.renderHumanPortrait = function (slideSel, cfg) {
  var root = document.querySelector(slideSel); if (!root) return;
  var figure = root.querySelector('.hp-figure');
  var host = root.querySelector('.silhouette-host');
  var leaders = root.querySelector('.hp-leaders');
  if (!figure || !host || !leaders) return;
  var SVGNS = 'http://www.w3.org/2000/svg';
  var kind = cfg.kind || 'man';
  var labels = (cfg.labels || []).slice(0, 6);
  var anchors = window.BODY_ANCHORS[kind] || {};
  var vb = (window.SILHOUETTE[kind] || window.SILHOUETTE.man).viewBox.split(/\s+/).map(Number);
  var dotR = Math.max(vb[2], vb[3]) * 0.011;

  injectSilhouette(host, kind, cfg.silhouette || {});

  // 清旧标签 + 旧色点（保留剪影 path）
  figure.querySelectorAll('.hp-tag').forEach(function (e) { e.remove(); });
  host.querySelectorAll('.hp-dot').forEach(function (e) { e.remove(); });

  var left = labels.filter(function (l) { return (l.side || 'left') === 'left'; });
  var right = labels.filter(function (l) { return l.side === 'right'; });
  var R = Math.max(left.length, right.length, 1);
  figure.style.setProperty('--hp-rows', R);

  var dots = [];
  function place(list, side) {
    var rows = _hpSpreadRows(list.length, R);
    list.forEach(function (l, i) {
      var tag = document.createElement('div');
      tag.className = 'hp-tag hp-tag-' + side;
      tag.style.gridColumn = side === 'left' ? '1' : '3';
      tag.style.gridRow = String(rows[i]);
      tag.style.justifySelf = side === 'left' ? 'end' : 'start';
      tag.style.setProperty('--hp-c', l.color || 'var(--accent)');
      tag.innerHTML =
        (l.num ? '<div class="hp-tag-num">' + l.num + '</div>' : '') +
        '<div class="hp-tag-h">' + (l.title || '') + '</div>' +
        (l.big ? '<div class="hp-tag-num-big">' + l.big + '</div>' : '') +
        (l.meta ? '<div class="hp-tag-meta">' + l.meta + '</div>' : '');
      figure.appendChild(tag);

      var a = anchors[l.part]; if (!a) return;
      var halo = document.createElementNS(SVGNS, 'circle');
      halo.setAttribute('class', 'hp-dot');
      halo.setAttribute('cx', a[0]); halo.setAttribute('cy', a[1]);
      halo.setAttribute('r', dotR * 2.4);
      halo.setAttribute('fill', l.color || '#3b82f6');
      halo.setAttribute('fill-opacity', '0.20');
      host.appendChild(halo);
      var dot = document.createElementNS(SVGNS, 'circle');
      dot.setAttribute('class', 'hp-dot');
      dot.setAttribute('cx', a[0]); dot.setAttribute('cy', a[1]);
      dot.setAttribute('r', dotR);
      dot.setAttribute('fill', l.color || '#3b82f6');
      dot.setAttribute('stroke', '#fff');
      dot.setAttribute('stroke-width', dotR * 0.5);
      host.appendChild(dot);
      dots.push({ tag: tag, dotEl: dot, color: l.color || '#3b82f6', side: side });
    });
  }
  place(left, 'left');
  place(right, 'right');

  function drawLeaders() {
    var scale = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--fit')) || 1;
    var fr = figure.getBoundingClientRect();
    var W = fr.width / scale, H = fr.height / scale;
    leaders.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    leaders.setAttribute('preserveAspectRatio', 'none');
    while (leaders.firstChild) leaders.removeChild(leaders.firstChild);
    dots.forEach(function (d) {
      var dr = d.dotEl.getBoundingClientRect();
      var dx = (dr.left + dr.width / 2 - fr.left) / scale;
      var dy = (dr.top + dr.height / 2 - fr.top) / scale;
      var tr = d.tag.getBoundingClientRect();
      var tx = ((d.side === 'left' ? tr.right : tr.left) - fr.left) / scale;
      var ty = (tr.top + tr.height / 2 - fr.top) / scale;
      var line = document.createElementNS(SVGNS, 'line');
      line.setAttribute('x1', tx); line.setAttribute('y1', ty);
      line.setAttribute('x2', dx); line.setAttribute('y2', dy);
      line.setAttribute('stroke', d.color);
      line.setAttribute('stroke-width', '2');
      line.setAttribute('stroke-dasharray', '6,5');
      line.setAttribute('stroke-linecap', 'round');
      line.setAttribute('opacity', '0.78');
      leaders.appendChild(line);
      var cap = document.createElementNS(SVGNS, 'circle');
      cap.setAttribute('cx', tx); cap.setAttribute('cy', ty);
      cap.setAttribute('r', '3'); cap.setAttribute('fill', d.color);
      leaders.appendChild(cap);
    });
  }
  requestAnimationFrame(drawLeaders);
  setTimeout(drawLeaders, 350);
  if (figure.__hpDraw) window.removeEventListener('resize', figure.__hpDraw);
  figure.__hpDraw = drawLeaders;
  window.addEventListener('resize', drawLeaders);
};
